import{_ as r,C as s,o as d,c as n,a3 as e,E as a}from"./chunks/framework.CZBGEXos.js";const b=JSON.parse('{"title":"Слой мажоров","description":"","frontmatter":{},"headers":[],"relativePath":"ru/customize/majors.md","filePath":"ru/customize/majors.md"}'),l={name:"ru/customize/majors.md"};function i(c,t,h,p,u,g){const o=s("Screenshot");return d(),n("div",null,[t[0]||(t[0]=e('<h1 id="слои-мажоров" tabindex="-1">Слой мажоров <a class="header-anchor" href="#слои-мажоров" aria-label="Permalink to &quot;Слой мажоров&quot;">​</a></h1><p>Слой мажоров рисует три вида значимой рыночной активности прямо на графике — каждый по той цене, по которой он произошёл:</p><table tabindex="0"><thead><tr><th>Слой</th><th>Что отмечает</th></tr></thead><tbody><tr><td><strong>Major trades</strong></td><td>Отдельные сделки из верхних 10% по размеру для этого тикера</td></tr><tr><td><strong>Clusters</strong></td><td>Одноминутные ценовые уровни, которые поглотили намного больше объёма, чем обычный уровень на этой монете</td></tr><tr><td><strong>Liquidations</strong></td><td>Принудительные закрытия позиций от $5 000</td></tr></tbody></table>',3)),a(o,{src:"majors",alt:"График со слоем мажоров: треугольники сделок и ячейка кластера",caption:"Мажоры на 1м графике — треугольники сделок, ячейки кластеров и подсказка одной крупной покупки"}),t[1]||(t[1]=e('<p>Это вспомогательный инструмент для чтения графика, а не сканер: он показывает, <strong>где</strong> прошёл крупный объём на графике, который вы и так смотрите.</p><h2 id="как-включить" tabindex="-1">Как включить <a class="header-anchor" href="#как-включить" aria-label="Permalink to &quot;Как включить&quot;">​</a></h2><p>Слой включается <strong>для каждого графика отдельно</strong>, не глобально. У каждого графика есть <strong>кнопка мажоров</strong> на панели инструментов, а стрелочка рядом открывает меню слоёв.</p><p>Также можно нажать клавишу слоя — по умолчанию <strong><kbd>M</kbd></strong> — держа курсор над графиком. Клавиша меняется во вкладке <strong>Home</strong> как <strong>Majors overlay key</strong>, рядом с клавишами инструментов рисования.</p><table tabindex="0"><thead><tr><th>Инструмент</th><th>Где доступен слой</th></tr></thead><tbody><tr><td><a href="/manual/ru/tools/analyzer.html">Analyzer</a></td><td>Каждая панель графика и полный экран</td></tr><tr><td><a href="/manual/ru/tools/knives.html">Knives</a></td><td>Только полный экран</td></tr><tr><td><a href="/manual/ru/tools/monitor.html">Monitor</a></td><td>Только полный экран</td></tr></tbody></table><p>В Knives и Monitor он намеренно ограничен полным экраном — карточка тикера слишком мала, чтобы маркеры по ценам можно было прочитать.</p><div class="info custom-block"><p class="custom-block-title">Если снять все три слоя, оверлей выключается</p><p>Когда вы выключаете все три слоя, выключается и сам оверлей, вместо того чтобы оставаться включённым и ничего не рисовать. Так что кнопки всегда соответствуют тому, что вы реально видите. Повторное включение возвращает все три слоя.</p></div><h2 id="как-читать-маркеры" tabindex="-1">Как читать маркеры <a class="header-anchor" href="#как-читать-маркеры" aria-label="Permalink to &quot;Как читать маркеры&quot;">​</a></h2><h3 id="крупные-сделки-—-треугольники" tabindex="-1">Крупные сделки — треугольники <a class="header-anchor" href="#крупные-сделки-—-треугольники" aria-label="Permalink to &quot;Крупные сделки — треугольники&quot;">​</a></h3><p>Треугольник указывает <strong>в ту сторону, куда толкал агрессор</strong>: вверх и зелёным для покупки, вниз и красным для продажи. Размер зависит от долларовой величины сделки относительно самой крупной на экране, так что самый крупный принт в поле зрения всегда имеет самый большой треугольник.</p><p>При наведении видно сторону, размер в долларах, цену, перцентиль, биржу и время.</p><div class="info custom-block"><p class="custom-block-title">Что означает перцентиль</p><p>Каждая сделка несёт перцентиль, который у неё был <strong>в момент исполнения</strong>. Пороги пересчитываются для каждого тикера по скользящему 4-часовому окну, так что <code>p99</code> означает, что сделка была в верхнем 1% <em>именно тогда</em>, а не относительно сегодняшнего дня.</p></div><h3 id="кластеры-—-залитые-ячеики" tabindex="-1">Кластеры — залитые ячейки <a class="header-anchor" href="#кластеры-—-залитые-ячеики" aria-label="Permalink to &quot;Кластеры — залитые ячейки&quot;">​</a></h3><p>Кластер — это одноминутный ценовой уровень, который удержал намного больше объёма, чем обычный уровень на этой монете. Рисуется залитой ячейкой по этой цене, с объёмом внутри.</p><ul><li><strong>Цвет</strong> — доминирующая сторона: зелёный, если покупки перевесили продажи, иначе красный.</li><li><strong>Число</strong> — объём именно доминирующей стороны, а не дельта.</li><li><strong>Прозрачность</strong> — относительно самого «громкого» уровня <em>среди видимых сейчас</em>, так что шкала перенормируется при зуме, а не сплющивается из-за одного гиганта за экраном.</li></ul><p>При наведении видно общий объём, покупки, продажи, дельту и разбивку по споту, если спотовый объём есть.</p><div class="warning custom-block"><p class="custom-block-title">«no clusters — price too stable» — это не ошибка</p><p>Уровни шириной около 0.05% — примерно $55 на BTC. Спокойная минута BTC не проходит такого расстояния, так что вся минута умещается в один уровень, и ни один не может выделиться на фоне соседей.</p><p>На очень стабильных и дорогих монетах кластеров может не быть <strong>вообще</strong>. Оверлей пишет об этом в строке состояния, вместо того чтобы выглядеть сломанным на самом популярном тикере из всех.</p></div><h3 id="ликвидации-—-ромбы" tabindex="-1">Ликвидации — ромбы <a class="header-anchor" href="#ликвидации-—-ромбы" aria-label="Permalink to &quot;Ликвидации — ромбы&quot;">​</a></h3><p>Ромб отмечает принудительное закрытие позиции, размер зависит от суммы.</p><p><strong>Цвет соответствует давлению, а не слову.</strong> Ликвидированный <em>лонг</em> — это принудительная <em>продажа</em>, поэтому рисуется красным и вниз; ликвидированный <em>шорт</em> — это принудительная покупка, рисуется зелёным. Это легче всего перепутать, и именно так это работает в ленте ликвидаций в окне Alerts.</p><p>При наведении написано словами — <code>long closed → forced sell</code> — а также размер, цена, биржа и время.</p><h2 id="строка-состояния" tabindex="-1">Строка состояния <a class="header-anchor" href="#строка-состояния" aria-label="Permalink to &quot;Строка состояния&quot;">​</a></h2><p>Оверлей пишет одну строку над графиком. Она намеренно честно сообщает о каждом ограничении, вместо того чтобы молча показывать неполную картину:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MAJORS · all venues · top 25 of 29k trades</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Фрагмент</th><th>Значение</th></tr></thead><tbody><tr><td><code>MAJORS · all venues</code></td><td>Маркеры со всех площадок, которые охватывает поток, — по умолчанию</td></tr><tr><td><code>MAJORS · binance+bybit</code> / <code>MAJORS · 4 of 7 venues</code></td><td>Вы сузили <a href="#venues">площадки</a>: до двух называются, больше — считаются</td></tr><tr><td><code>clusters all venues</code></td><td>Показывается, когда включён фильтр площадок, — кластеры по нему не фильтруются</td></tr><tr><td><code>candles &lt;биржа&gt;</code></td><td>Показывается, когда свечи с биржи, с которой маркеры приходить не могут</td></tr><tr><td><code>candles spot</code></td><td>Показывается, когда вы смотрите спотовый график</td></tr><tr><td><code>top N of M trades</code></td><td><strong>В окне было M, нарисованы только N крупнейших</strong> — см. <a href="#markers-drawn">Markers drawn</a></td></tr><tr><td><code>no clusters — price too stable</code></td><td>Объяснено выше</td></tr><tr><td><code>7d max</code></td><td>Таймфрейм уходит дальше, чем сервер хранит данные</td></tr><tr><td><code>connecting…</code> / <code>auth failed</code> / <code>feed error</code> / <code>no data for this symbol</code></td><td>Состояние подключения</td></tr></tbody></table><h3 id="откуда-берутся-маркеры" tabindex="-1">Откуда берутся маркеры <a class="header-anchor" href="#откуда-берутся-маркеры" aria-label="Permalink to &quot;Откуда берутся маркеры&quot;">​</a></h3><p>Поток охватывает семь площадок: <strong>Binance</strong> perp и spot, <strong>Bybit</strong> perp и spot, а также перпы <strong>OKX</strong>, <strong>Gate.io</strong> и <strong>Hyperliquid</strong>. Маркеры для символа собираются со всех них, с какой бы биржи ни были свечи. Сузить это можно настройкой <a href="#venues">Venues</a>.</p><p>Если свечи с биржи, которой нет среди площадок маркеров, строка состояния покажет <code>candles &lt;биржа&gt;</code>. Sentaro никогда не скрывает это молча.</p><p>История уходит на <strong>7 дней</strong> назад. На таймфрейме шире этого левая часть графика просто не имеет маркеров, а в строке появляется <code>7d max</code>.</p><h2 id="настроики" tabindex="-1">Настройки <a class="header-anchor" href="#настроики" aria-label="Permalink to &quot;Настройки&quot;">​</a></h2>',30)),a(o,{src:"majors-settings",alt:"Настройки слоя мажоров во вкладке Home",caption:"Home → Majors overlay"}),t[2]||(t[2]=e('<p>Фильтры находятся во вкладке <strong>Home</strong>, в секции <strong>Majors overlay</strong>. Они действуют на все графики во всех инструментах.</p><h3 id="markers-drawn" tabindex="-1">Markers drawn <a class="header-anchor" href="#markers-drawn" aria-label="Permalink to &quot;Markers drawn&quot;">​</a></h3><p>Сколько крупнейших рисовать, <strong>отдельно для каждого типа</strong>. Диапазон <strong>от 25 до 1500</strong> с шагом 25, по умолчанию 25.</p><p>Это настройка именно для <strong>сделок</strong>. В загруженном окне их тысячи, так что на график попадают только крупнейшие — и строка состояния сообщает, когда такое обрезание произошло.</p><p>Для кластеров и ликвидаций это редко имеет значение: их обычно намного меньше лимита, так что на деле решают их пороги размера ниже.</p><h3 id="cluster-strength" tabindex="-1">Cluster strength <a class="header-anchor" href="#cluster-strength" aria-label="Permalink to &quot;Cluster strength&quot;">​</a></h3><p>Скрывает ценовые уровни, которые держат меньше, чем столько объёмов обычного уровня на этой монете. Диапазон <strong>от 3× до 25×</strong> с шагом 0.5, по умолчанию 5.5×.</p><ul><li><strong>3×</strong> — всё, что хранит сервер, самое мягкое возможное значение.</li><li><strong>6×</strong> — только явно сильные уровни.</li></ul><p>Поднять это — самый быстрый способ успокоить шумный график, не потеряв важных уровней.</p><h3 id="liquidation-size" tabindex="-1">Liquidation size <a class="header-anchor" href="#liquidation-size" aria-label="Permalink to &quot;Liquidation size&quot;">​</a></h3><p>Скрывает ликвидации меньше этой суммы. Диапазон <strong>от $5 000 до $1 000 000</strong> с шагом $5 000, по умолчанию $15 000.</p><p>$5 000 — собственный порог сервера: меньшего он не хранит вообще, так что минимальное значение уже означает «вообще всё, что есть».</p><h3 id="venues" tabindex="-1">Venues <a class="header-anchor" href="#venues" aria-label="Permalink to &quot;Venues&quot;">​</a></h3><p>С каких площадок могут приходить крупные сделки и ликвидации. Ряд кнопок, по одной на площадку, с пометкой <code>perp</code> или <code>spot</code>. По умолчанию <strong>all</strong>.</p><p>Нажмите на кнопку, чтобы выключить или включить площадку. Счётчик показывает, сколько включено, например <code>4/7</code>. <strong>All venues</strong> сбрасывает выбор. Выключение последней площадки возвращает все, так что оверлей никогда не остаётся включённым без данных.</p><div class="info custom-block"><p class="custom-block-title">Кластеры это игнорируют</p><p>Кластер объединяет все площадки монеты в один ценовой уровень, так что в нём не остаётся ничего, что можно отфильтровать по площадке. Когда фильтр включён, строка состояния напоминает об этом надписью <code>clusters all venues</code>.</p></div><h2 id="связанное" tabindex="-1">Связанное <a class="header-anchor" href="#связанное" aria-label="Permalink to &quot;Связанное&quot;">​</a></h2><ul><li><a href="/manual/ru/customize/chart-colors.html">Графики и рисование</a> — цвета свечей, инструменты рисования и клавиши, рядом с которыми живёт клавиша оверлея</li><li><a href="/manual/ru/tools/analyzer.html">Analyzer</a> — инструмент, где оверлей доступен на каждой панели</li></ul>',18))])}const _=r(l,[["render",i]]);export{b as __pageData,_ as default};
